import {emptyState, applyOperation, validateState, labels, uid} from './domain.js';
import {demoState} from './demo.js';
const KEY='nexo.workspace.v1';
const colors={violet:['#9782cf','#f1ecfa'],orange:['#d29c80','#faf0e9'],green:['#81a58e','#edf5ef'],blue:['#7e9fc5','#edf2fa'],pink:['#bd8da7','#f8edf4']};
const paths={
 grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
 sun:'M12 3v1 M12 20v1 M3 12h1 M20 12h1 M5.6 5.6l.7.7 M17.7 17.7l.7.7 M5.6 18.4l.7-.7 M17.7 6.3l.7-.7 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M20 15.2A8.5 8.5 0 0 1 8.8 4 8.5 8.5 0 1 0 20 15.2z',
 inbox:'M4 4h16l2 11v5H2v-5L4 4z M2 15h6l2 3h4l2-3h6',
 folder:'M3 7V5h6l2 2h10v13H3V7z',
 archive:'M4 7v14h16V7 M3 3h18v4H3z M9 11h6',
 plus:'M12 5v14 M5 12h14', chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',
 arrow:'M5 12h14 M14 7l5 5-5 5',
 search:'M17 17l4 4 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
 bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',
 spark:'M12 3l2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3z M20 2v4 M18 4h4',
 settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M10 2h4l1 3 3 1 3 1v4l-2 2-1 3-1 3h-4l-2-2-3-1-3-1v-4l2-2 1-3 1-3z',
 check:'M5 12l4 4L19 6',circle:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
 clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 6v6l4 2',
 board:'M3 4h18v16H3z M9 4v16 M15 4v16 M5 8h2 M11 8h2 M17 8h2',
 list:'M8 6h13 M8 12h13 M8 18h13 M3 6h1 M3 12h1 M3 18h1',
 activity:'M2 12h5l3-8 4 16 3-8h5',
 flag:'M5 21V3 M5 3c5-3 9 3 14 0v10c-5 3-9-3-14 0',
 menu:'M4 6h16 M4 12h16 M4 18h16',close:'M6 6l12 12 M6 18L18 6',
 link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2',
 github:'M9 19c-5 2-5-3-7-3 M16 22v-4c0-1-.5-2-1-2 5-.6 7-3 7-6 0-2-.5-3-2-4 0-1 0-3-.5-4-2-.5-4 1-4 1a12 12 0 0 0-7 0S6.5 1.5 4.5 2C4 3 4 5 4 6c-1.5 1-2 2-2 4 0 3 2 5.4 7 6-.5 0-1 1-1 2v4',
 code:'M8 6l-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',
 download:'M12 3v12 M7 10l5 5 5-5 M4 15v6h16v-6',
 upload:'M12 16V4 M7 9l5-5 5 5 M4 15v6h16v-6',
 copy:'M9 9h12v12H9z M15 9V3H3v12h6',
 trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',
 pause:'M8 4v16 M16 4v16',play:'M7 3l14 9-14 9V3z',
 rocket:'M8 16l-4 4 M5 14l-2-4 5-2 M10 19l4 2 2-5 M8 16C6 8 13 2 22 2c0 9-6 16-14 14z M15 7l2 2',
 leaf:'M5 19C0 8 12 3 21 3c0 12-4 20-16 16z M5 19L16 8',
 nodes:'M8 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M22 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M8 20a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M8 5l8 5 M8 19l8-5',
 bag:'M4 7h16l1 14H3L4 7z M8 8V6a4 4 0 0 1 8 0v2',
 cloud:'M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13-2 6 6 0 0 1 0 12H6z',
 lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',
 external:'M14 3h7v7 M21 3l-11 11 M11 3H3v18h18v-8',
 target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M12 12h.01'
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.circle}"/></svg>`;
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const theme=p=>{const c=colors[p?.color]||colors.violet;return `--project:${c[0]};--project-bg:${c[1]}`;};
const initial=p=>esc((p?.name||'N').slice(0,1).toUpperCase());
const projectIcon=p=>icon(({orange:'rocket',violet:'nodes',green:'bag',blue:'leaf',pink:'spark'})[p.color]||'folder');
const priorityLabel={high:'Alta',medium:'Media',low:'Baja'};
const priorities={high:0,medium:1,low:2};
const THEME_KEY='nexo.theme.v1';
let appearance=localStorage.getItem(THEME_KEY)||((window.matchMedia?.('(prefers-color-scheme: dark)').matches)?'dark':'light');
function applyAppearance(){document.documentElement.dataset.theme=appearance;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',appearance==='dark'?'#171821':'#7060da');}
applyAppearance();
let state=emptyState(),local=null,route='overview',selected=null,tab='list',search='',priority='all',projectFilter='all',taskStatus='open',jobs=[],claudeAvailable=null,openedTask=null,installEvent=null;
let operationQueue=Promise.resolve();
const app=document.querySelector('#app'),overlay=document.querySelector('#overlay');
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),4300);}
async function request(url,options={}){const res=await fetch(url,{...options,headers:{'Content-Type':'application/json','X-Nexo-Token':local?.token||'',...options.headers}});const data=await res.json();if(!res.ok)throw Error(data.error||'No se pudo completar la operación.');return data;}
function persist(s){localStorage.setItem(KEY,JSON.stringify(s));}
async function mutate(op){
  const run=operationQueue.then(async()=>{
    const s=local?await request('/api/operation',{method:'POST',body:JSON.stringify(op)}):applyOperation(JSON.parse(localStorage.getItem(KEY)||'null')||state,op);
    if(!local)persist(s);state=s;render();return s;
  });operationQueue=run.catch(()=>{});return run;
}
async function replace(s){validateState(s);if(local)s=await request('/api/import',{method:'POST',body:JSON.stringify(s)});else persist(s);state=s;render();}
const projectById=id=>state.projects.find(p=>p.id===id);
const activeProjects=()=>state.projects.filter(p=>p.status==='active');
const acceptedTasks=()=>state.tasks.filter(t=>!t.suggested&&projectById(t.projectId)?.status!=='archived');
function scopeTasks(){let tasks=acceptedTasks();if(selected)tasks=tasks.filter(t=>t.projectId===selected);if(route==='today')tasks=tasks.filter(t=>t.today);return tasks;}
function visibleTasks(){return scopeTasks().filter(t=>(tab!=='list'||taskStatus==='all'||(taskStatus==='done'?t.status==='done':t.status!=='done'))&&(priority==='all'||t.priority===priority)&&(projectFilter==='all'||t.projectId===projectFilter)&&(!search||(t.title+' '+t.description+' '+projectById(t.projectId)?.name).toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>priorities[a.priority]-priorities[b.priority]);}
function badge(p){return `<span class="project-tag" style="${theme(p)}">${esc(p?.name||'Proyecto')}</span>`;}
function progress(p){const all=state.tasks.filter(t=>t.projectId===p.id&&!t.suggested);return {done:all.filter(t=>t.status==='done').length,total:all.length,percent:all.length?Math.round(all.filter(t=>t.status==='done').length/all.length*100):0};}
function sidebar(){const suggestions=state.tasks.filter(t=>t.suggested).length;return `<aside class="sidebar" aria-label="Navegación principal">
 <a class="brand" href="#overview" data-route="overview" aria-label="Nexo, inicio"><img src="./icon.svg" alt="">nexo<span>alpha</span></a>
 <button class="workspace-switch" data-action="settings"><span class="workspace-icon">M</span><span class="workspace-copy"><b>${esc(state.settings?.name||'Mi espacio')}</b><small>Workspace personal</small></span>${icon('down')}</button>
 <div class="sidebar-scroll"><div class="section-label">PRINCIPAL</div><nav class="nav-list">
 ${[['overview','grid','Vista general'],['today','sun','Mi día'],['inbox','inbox','Sugerencias']].map(([id,i,label])=>`<button class="nav-item ${route===id&&!selected?'active':''}" data-route="${id}">${icon(i)}${label}${id==='today'?`<span class="count">${acceptedTasks().filter(t=>t.today&&t.status!=='done').length}</span>`:id==='inbox'&&suggestions?`<span class="count">${suggestions}</span>`:''}</button>`).join('')}
 </nav><div class="section-label">MIS PROYECTOS<button class="icon-btn" data-action="new-project" aria-label="Crear proyecto">${icon('plus')}</button></div>
 <nav class="nav-list">${state.projects.filter(p=>p.status!=='archived').map(p=>`<button class="nav-item project-nav ${selected===p.id?'active':''} ${p.status==='paused'?'paused':''}" data-project="${esc(p.id)}"><span class="project-dot" style="${theme(p)}"></span><span class="name">${esc(p.name)}</span><span class="small-muted">${state.tasks.filter(t=>t.projectId===p.id&&!t.suggested&&t.status!=='done').length}</span></button>`).join('')}
 <button class="new-project-side" data-action="new-project">${icon('plus')}Nuevo proyecto</button></nav>
 <button class="nav-item ${route==='archived'?'active':''}" data-route="archived">${icon('archive')}Archivados</button></div>
 <div class="sidebar-bottom"><button class="claude-mini" data-route="integrations"><span class="spark">${icon('spark')}</span><span><b>Claude Code</b><small>${local?'MCP disponible':'Conectá tu copiloto'}</small></span><span class="status-dot ${local?'local':''}"></span></button>
 <div class="profile"><span class="avatar">${state.demo?'MC':'YO'}</span><span><b>${state.demo?'Máximo Cobeaga':'Tu espacio personal'}</b><small>${local?'Guardado en tu equipo':'Guardado en este navegador'}</small></span><button class="icon-btn" data-action="settings" aria-label="Configuración">${icon('settings')}</button></div></div></aside>`;}
function header(){const title=selected?projectById(selected)?.name:({overview:'Vista general',today:'Mi día',inbox:'Sugerencias',projects:'Proyectos',integrations:'Claude Code',archived:'Archivados'})[route];const dark=appearance==='dark';return `<header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir navegación">${icon('menu')}</button><div class="breadcrumb">${icon('grid')}<span>${esc(state.settings?.name||'Mi espacio')}</span>${icon('chevron')}<strong>${esc(title)}</strong></div><div class="top-actions"><button class="global-search" data-action="search">${icon('search')}<span>Buscar algo…</span><kbd class="kbd">⌘ K</kbd></button><span class="divider"></span><button class="icon-btn theme-toggle" data-action="toggle-theme" aria-label="Cambiar a tema ${dark?'claro':'oscuro'}" title="Cambiar a tema ${dark?'claro':'oscuro'}" aria-pressed="${dark}">${icon(dark?'sun':'moon')}</button><button class="icon-btn" data-route="inbox" aria-label="Ver sugerencias">${icon('bell')}</button><button class="avatar" data-action="settings" aria-label="Abrir configuración">${state.demo?'MC':'YO'}</button></div></header>`;}
function intro(){
 const p=selected?projectById(selected):null;
 const titles={overview:['UN POCO DE FOCO. MUCHO MÁS AVANCE.','Tu espacio, en movimiento.','Todo lo que estás construyendo, con un próximo paso claro.'],today:['HACÉ ESPACIO PARA LO IMPORTANTE','Un buen día para avanzar.','Elegí pocas tareas. Terminá algo que te acerque a tu objetivo.'],projects:['IDEAS CON UN LUGAR PROPIO','Tus proyectos.','Cada proyecto, su objetivo. Todos, en el mismo lugar.'],inbox:['LA IA PROPONE. VOS DECIDÍS.','Un próximo paso posible.','Revisá las sugerencias antes de sumarlas a tus pendientes.'],integrations:['TU TABLERO + TU COPILOTO','Trabajá con Claude Code.','El contexto queda guardado. El próximo paso también.'],archived:['EN PAUSA, NO PERDIDOS','Proyectos archivados.','Podés restaurarlos cuando quieras volver a empezar.']};
 const [eye,title,sub]=p?['MIS PROYECTOS / '+({active:'EN MARCHA',paused:'EN PAUSA',archived:'ARCHIVADO'})[p.status],p.name,p.description||'Un objetivo claro. Un paso a la vez.']:titles[route]||titles.overview;
 return `<section class="intro"><div><div class="eyebrow">${esc(eye)}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="intro-actions">${route==='integrations'?'':`<button class="btn" data-action="analyze">${icon('spark')}Analizar con IA</button><button class="btn primary" data-action="${route==='projects'||!state.projects.length?'new-project':'new-task'}">${icon('plus')}${route==='projects'||!state.projects.length?'Nuevo proyecto':'Nueva tarea'}</button>`}</div></section>`;
}
function stats(){const tasks=selected?acceptedTasks().filter(t=>t.projectId===selected):acceptedTasks();return `<div class="stats">${[
 [selected?'Pendientes':'Proyectos activos',selected?tasks.filter(t=>t.status==='pending').length:activeProjects().length,'folder',selected?'por empezar':'con ganas de avanzar'],
 ['En progreso',tasks.filter(t=>t.status==='doing').length,'activity','paso a paso'],
 ['Para hoy',tasks.filter(t=>t.today&&t.status!=='done').length,'sun','un poco de foco'],
 ['Terminadas',tasks.filter(t=>t.status==='done').length,'check','cada paso cuenta']
 ].map(([label,value,i,note])=>`<div class="stat"><div class="stat-head">${label}${icon(i)}</div><div class="stat-value">${value}<span class="stat-note">${note}</span>${i==='check'&&value?'<span class="trend">¡Bien ahí!</span>':''}</div></div>`).join('')}</div>`;}
function projectCard(p){const {done,total,percent}=progress(p);return `<button class="project-card" data-project="${esc(p.id)}" style="${theme(p)}"><div class="row"><span class="project-logo">${projectIcon(p)}</span><div><h3>${esc(p.name)}</h3><div class="project-sub">${total} ${total===1?'tarea':'tareas'}</div></div><span class="project-state ${p.status==='paused'?'paused':''}">${p.status==='paused'?'En pausa':'En marcha'}</span></div><p class="desc">${esc(p.description||p.goal||'Listo para dar el primer paso.')}</p><div class="progress-track"><div class="progress-fill" style="width:${percent}%"></div></div><div class="project-footer"><span>${done} de ${total} terminadas</span><b>${percent}%</b></div></button>`;}
function taskCard(t){const p=projectById(t.projectId);const blocked=(t.dependsOn||[]).some(id=>state.tasks.find(task=>task.id===id)?.status!=='done');return `<article class="task-card ${t.status==='done'?'is-done':''}" tabindex="0" role="button" aria-label="Abrir tarea: ${esc(t.title)}" draggable="true" data-task="${esc(t.id)}"><div class="task-label-row">${badge(p)}${blocked?'<span class="blocked-tag" title="Esperando una dependencia">Bloqueada</span>':''}<span class="task-id">NX-${state.tasks.indexOf(t)+1}</span></div><h3>${esc(t.title)}</h3>${t.description?`<p class="task-desc">${esc(t.description)}</p>`:''}<div class="task-bottom"><span class="priority ${esc(t.priority)}">${icon('flag')}${priorityLabel[t.priority]}</span>${t.today&&t.status!=='done'?'<span class="today-dot" title="Para hoy"></span>':''}<span class="task-estimate">${t.estimate?icon('clock')+esc(t.estimate):t.status==='done'?icon('check'):''}</span></div></article>`;}
function boardToolbar(){return `<div class="board-toolbar"><div class="tabs">${[['list','list','Por prioridad'],['board','board','Kanban'],['activity','activity','Actividad']].map(([id,i,title])=>`<button class="tab ${tab===id?'active':''}" data-tab="${id}">${icon(i)}${title}</button>`).join('')}</div><div class="filters"><label class="inline-search">${icon('search')}<input id="board-search" placeholder="Buscar tarea…" value="${esc(search)}" aria-label="Buscar en el tablero"></label>${selected?'':`<select id="project-filter" aria-label="Filtrar por proyecto"><option value="all">Todos los proyectos</option>${state.projects.filter(p=>p.status!=='archived').map(p=>`<option value="${esc(p.id)}" ${projectFilter===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`}${tab==='list'?`<select id="status-filter" aria-label="Filtrar por estado"><option value="open" ${taskStatus==='open'?'selected':''}>Sin terminar</option><option value="done" ${taskStatus==='done'?'selected':''}>Terminadas</option><option value="all" ${taskStatus==='all'?'selected':''}>Todos los estados</option></select>`:''}<select id="priority-filter" aria-label="Filtrar por prioridad"><option value="all">Prioridad</option>${Object.entries(priorityLabel).map(([v,l])=>`<option value="${v}" ${priority===v?'selected':''}>${l}</option>`).join('')}</select></div></div>`;}
function boardContents(){
 const tasks=visibleTasks();
 if(tab==='activity')return activityView();
 if(tab==='list')return tasks.length?`<div class="priority-board">${['high','medium','low'].filter(pr=>tasks.some(t=>t.priority===pr)).map(pr=>`<section class="priority-group"><div class="priority-group-head"><span class="priority ${pr}">${icon('flag')}</span><h3>${priorityLabel[pr]} prioridad</h3><span>${tasks.filter(t=>t.priority===pr).length}</span><span class="priority-line"></span></div><div class="priority-rows">${tasks.filter(t=>t.priority===pr).map(t=>{const p=projectById(t.projectId);return `<article class="priority-row ${t.status==='done'?'is-done':''}" data-task="${esc(t.id)}" role="button" tabindex="0" aria-label="Abrir tarea: ${esc(t.title)}"><span class="row-status ${t.status}">${icon(t.status==='done'?'check':t.status==='doing'?'play':t.status==='review'?'circle':'circle')}</span><div class="priority-row-main"><h3>${esc(t.title)}</h3><p>${esc(t.description||'Un próximo paso para avanzar.')}</p></div>${badge(p)}<span class="row-state"><span class="status-dot ${t.status}"></span>${labels[t.status]}</span><span class="row-estimate">${t.estimate?icon('clock')+esc(t.estimate):'—'}</span><span class="row-next">${t.today&&t.status!=='done'?icon('sun'):icon('chevron')}</span></article>`;}).join('')}</div></section>`).join('')}</div>`:empty('Sin tareas en esta vista','Probá otro filtro o creá tu primer pendiente.','new-task','Crear tarea');
 return `<div class="kanban">${Object.entries(labels).map(([status,label])=>`<section class="column" data-drop-status="${status}" aria-label="${label}"><div class="column-head"><span class="status-dot ${status}"></span>${label}<span class="column-count">${tasks.filter(t=>t.status===status).length}</span><button data-action="new-task" data-status="${status}" aria-label="Agregar tarea a ${label}">${icon('plus')}</button></div>${tasks.filter(t=>t.status===status).map(taskCard).join('')}${!tasks.some(t=>t.status===status)?'<div class="empty-column">Un lugar para<br>tu próximo avance.</div>':''}<button class="column-add" data-action="new-task" data-status="${status}">${icon('plus')}Agregar tarea</button></section>`).join('')}</div>`;
}
function activityView(){return state.activity.length?`<div class="activity-list">${state.activity.map(a=>`<div class="activity-item"><span class="activity-icon">${icon('activity')}</span><p>${esc(a.text)}</p><time>${new Date(a.at).toLocaleDateString('es-AR',{day:'numeric',month:'short'})}</time></div>`).join('')}</div>`:empty('Cada avance deja una huella','Cuando empieces a trabajar, vas a ver la actividad acá.');}
function empty(title,sub,action,label){return `<div class="empty-state">${icon('leaf')}<h3>${esc(title)}</h3><p>${esc(sub)}</p>${action?`<button class="btn primary" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`;}
function projectDetails(){
 const p=projectById(selected);const dates=state.tasks.filter(t=>t.projectId===p.id&&t.updatedAt).map(t=>t.updatedAt);const last=[p.updatedAt,p.createdAt,...dates].filter(Boolean).sort().at(-1);
 const safeWebsite=/^https?:\/\//.test(p.website||'')?p.website:null;
 return `<section class="project-profile"><div class="profile-overview"><div class="profile-title-row"><span class="project-logo large-logo" style="${theme(p)}">${projectIcon(p)}</span><div><span class="eyebrow">EL PROYECTO, EN CONTEXTO</span><h2>¿Qué es ${esc(p.name)}?</h2></div><button class="btn" data-action="edit-project">${icon('settings')}Editar perfil</button></div><p class="project-about">${esc(p.about||p.description||'Contá de qué se trata este proyecto, a quién ayuda y por qué lo empezaste.')}</p>${p.stack?`<div class="stack-tags">${p.stack.split(',').map(x=>x.trim()).filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}<div class="profile-goal"><span>${icon('target')}</span><div><h3>Lo considero terminado cuando…</h3><p>${esc(p.goal||'Definí el objetivo para priorizar lo que realmente falta.')}</p></div></div><div class="profile-resume"><span>${icon('activity')}</span><div><h3>¿Dónde lo dejé?</h3><p>${esc(p.nextStep||'Todavía no registraste el próximo paso. Agregalo al perfil o pedile a Claude que lo guarde al cerrar la sesión.')}</p></div></div>${p.notes?`<div class="project-notes"><h3>Notas para mi yo del futuro</h3><p>${esc(p.notes)}</p></div>`:''}${p.lastAnalysis?`<div class="project-notes"><h3>Última lectura de Claude</h3><p>${esc(p.lastAnalysis)}</p></div>`:''}</div><aside class="project-context"><h3>A mano, cuando lo necesites.</h3><div class="context-item"><label>${icon('folder')}Carpeta local</label>${p.path?`<code>${esc(p.path)}</code><button class="context-link" data-action="copy-path">Copiar ruta ${icon('copy')}</button>`:'<p class="muted">Sin carpeta vinculada</p>'}</div><div class="context-item"><label>${icon('github')}Repositorio</label>${p.repository&&/^https:\/\/github\.com\//.test(p.repository)?`<a href="${esc(p.repository)}" target="_blank" rel="noopener noreferrer">Abrir en GitHub ${icon('external')}</a>`:'<p class="muted">Solo en mi equipo</p>'}</div>${safeWebsite?`<div class="context-item"><label>${icon('link')}Proyecto online</label><a href="${esc(safeWebsite)}" target="_blank" rel="noopener noreferrer">Visitar proyecto ${icon('external')}</a></div>`:''}<div class="context-item"><label>${icon('code')}Cómo ejecutarlo</label>${p.runCommand?`<code>${esc(p.runCommand)}</code><button class="context-link" data-action="copy-run">Copiar comando ${icon('copy')}</button>`:'<p class="muted">Agregá el comando de inicio al perfil.</p>'}</div><div class="context-item"><label>${icon('clock')}Último movimiento</label><p>${last?new Date(last).toLocaleDateString('es-AR',{day:'numeric',month:'long',year:'numeric'}):'Todavía no hay actividad'}</p></div></aside></section>`;
}
function inbox(){const suggestions=state.tasks.filter(t=>t.suggested);return suggestions.length?suggestions.map(t=>`<article class="suggestion"><div class="suggestion-top">${badge(projectById(t.projectId))}<span class="small-muted">${icon('spark')} Propuesta de IA</span></div><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><div class="evidence">${icon('code')} ${esc(t.source||'Sin evidencia. Revisá la propuesta antes de aceptarla.')}</div><div class="suggestion-actions"><button class="btn primary" data-accept="${esc(t.id)}">${icon('check')}Sumar al tablero</button><button class="btn subtle" data-discard="${esc(t.id)}">Descartar</button></div></article>`).join(''):empty('Todo revisado','Cuando Claude proponga pendientes, vas a poder revisarlos acá.','analyze','Analizar un proyecto');}
function mcpCommand(){return local?`claude mcp add --transport stdio --scope user nexo -- node "${local.mcpPath}"`:'claude mcp add --transport stdio --scope user nexo -- node "RUTA_A_NEXO/local/mcp.mjs"';}
function integration(){return `<div class="integration-grid"><section class="connection-panel"><h2>${icon('spark')} Un tablero que Claude puede usar.</h2><p>Conectá Nexo por MCP para que Claude consulte tus proyectos, proponga tareas y registre los avances de cada sesión.</p><div class="steps"><div class="step"><span class="step-number">1</span><div><b>Ejecutá Nexo en tu equipo</b><p>${local?'Ya estás usando el servicio local. Tus tareas y Claude compartirán el mismo espacio.':'Descargá el código, descomprimilo e iniciá el servicio con Node.js 22 o superior.'}</p>${!local?'<pre>npm start</pre><a class="btn" href="./nexo-source.zip" download>'+icon('download')+'Descargar código fuente</a>':''}</div></div><div class="step"><span class="step-number">2</span><div><b>Agregá Nexo a Claude Code</b><p>Ejecutá este comando en tu terminal. Después, abrí una nueva sesión de Claude.</p><pre>${esc(mcpCommand())}</pre><button class="btn" data-action="copy-mcp">${icon('copy')}Copiar comando</button>${!local?'<p>Reemplazá RUTA_A_NEXO por la carpeta donde descomprimiste el proyecto.</p>':''}</div></div><div class="step"><span class="step-number">3</span><div><b>Dale contexto y un objetivo</b><p>Abrí la carpeta de tu proyecto con Claude Code. Pedile que consulte Nexo, lea el objetivo y proponga tareas pequeñas con evidencia del código.</p></div></div></div></section><div><section class="connection-panel"><h2>Hecho para continuar.</h2><p>Al cerrar una sesión, pedile a Claude que registre qué avanzó, qué está bloqueado y cuál es el siguiente paso.</p><ul class="feature-list"><li>${icon('check')}Proyectos y carpetas independientes</li><li>${icon('check')}Sugerencias antes de llenar tu tablero</li><li>${icon('check')}Tareas compartidas con el servicio local</li><li>${icon('check')}Historial entre sesiones</li></ul></section><div class="install-hint"><b>${local?'Modo local activo':'Esta es la versión web'}</b><br>${local?'El botón Analizar utiliza tu instalación de Claude Code. Necesitás tener el CLI nativo instalado y una sesión iniciada.': 'Los datos se guardan en este navegador. La app web publicada y la app local todavía no se sincronizan: usá exportar e importar para trasladar tu espacio.'}</div><div class="settings-actions" style="margin-top:15px"><button class="btn" data-action="export">${icon('download')}Exportar espacio</button><button class="btn" data-action="import">${icon('upload')}Importar</button>${installEvent?'<button class="btn" data-action="install">Instalar web app</button>':''}</div></div></div>`;}
function mainContent(){let body='';let projectSection='';
 if(route==='integrations')return integration();
 if(route==='inbox')return inbox();
 if(route==='archived'){const ps=state.projects.filter(p=>p.status==='archived');return ps.length?`<div class="project-grid">${ps.map(p=>`<div>${projectCard(p)}<button class="btn" style="margin-top:10px" data-restore="${esc(p.id)}">Restaurar proyecto</button></div>`).join('')}</div>`:empty('Un poco de espacio para lo nuevo','Tus proyectos archivados aparecerán acá.');}
 if(route==='projects')return state.projects.some(p=>p.status!=='archived')?`<div class="project-grid">${state.projects.filter(p=>p.status!=='archived').map(projectCard).join('')}</div>`:empty('Todo empieza con una idea','Agregá tu primer proyecto y definí qué querés terminar.','new-project','Crear mi primer proyecto');
 if(selected)body+=projectDetails();
 body+=stats();
 if(route==='overview'&&!selected&&state.projects.length){projectSection=`<section><div class="section-heading"><h2>Proyectos en marcha <span class="small-muted">· ${activeProjects().length}</span></h2><button class="secondary-link" data-route="projects">Ver todos ${icon('arrow')}</button></div><div class="project-grid">${activeProjects().slice(0,3).map(projectCard).join('')||'<p class="small-muted">Activá un proyecto para volver a avanzar.</p>'}</div></section>`;}
 if(route==='today')body+=`<div class="focus-note">${icon('sun')}<span><b>Menos es más.</b> Tu objetivo es trabajar en hasta ${Number(state.settings?.dailyLimit)||3} tareas hoy. Marcá “Para hoy” desde cualquier tarea.</span></div>`;
 if(!state.projects.length)return body+empty('Tu próximo proyecto empieza acá','Vinculá una carpeta o un repositorio y anotá el objetivo.','new-project','Crear mi primer proyecto');
 body+=`<section><div class="board-heading"><div><h2>${route==='today'?'Tu foco de hoy.':selected?'Un paso más cerca.':'El próximo paso, claro.'}</h2><p>${route==='today'?'Un poco de constancia hace la diferencia.':'Elegí una tarea. Dale espacio. Seguí avanzando.'}</p></div><button class="btn" data-action="new-task">${icon('plus')}Agregar tarea</button></div>${boardToolbar()}<div id="board-contents">${boardContents()}</div></section>`;return body+(projectSection?`<div style="margin-top:30px">${projectSection}</div>`:'');
}
function render(){
 if(selected&&!projectById(selected)){selected=null;route='overview';}
 const running=jobs.find(j=>j.status==='running');
 app.innerHTML=sidebar()+`<main class="main">${header()}<div class="content">${intro()}${state.demo?'<div class="demo-banner">'+icon('spark')+'<span>Estás explorando datos de ejemplo. No analizamos tus proyectos reales.</span><button data-action="start-fresh">Empezar con mis proyectos '+icon('arrow')+'</button></div>':''}${running?'<div class="job-banner"><span class="spinner"></span>Claude está revisando '+esc(projectById(running.projectId)?.name)+'. Las propuestas aparecerán en Sugerencias.</div>':''}${mainContent()}<footer class="bottom-note"><span>${icon('lock')}${state.demo?'Espacio de ejemplo':local?'Tus proyectos, en tu equipo.':'Guardado en este navegador.'}</span><span>Un paso a la vez. Ese es el plan. ${icon('leaf')}</span></footer></div></main>`;
}
function navigate(r,project=null){route=r;selected=project;tab='list';search='';priority='all';projectFilter='all';taskStatus='open';location.hash=project?'project/'+encodeURIComponent(project):r;render();window.scrollTo(0,0);}
function closeOverlay(){overlay.innerHTML='';openedTask=null;document.body.style.overflow='';document.querySelector('[data-action="new-task"], [data-action="new-project"], .brand')?.focus({preventScroll:true});}
function openModal(title,content,{large=false,drawer=false}={}){document.body.style.overflow='hidden';overlay.innerHTML=`<div class="backdrop ${drawer?'drawer-wrap':''}"><section role="dialog" aria-modal="true" aria-labelledby="dialog-title" class="${drawer?'drawer':'modal'+(large?' large':'')}"><div class="${drawer?'drawer-top':'modal-head'}"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div><div class="${drawer?'drawer-body':'modal-body'}">${content}</div></section></div>`;setTimeout(()=>(overlay.querySelector('input:not([type=hidden]),textarea,select')||overlay.querySelector('button'))?.focus(),30);}
function errorInForm(e){overlay.querySelector('.form-error')?.remove();const el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');el.textContent=e.message||String(e);overlay.querySelector('form')?.append(el);}
function projectForm(edit=false){const p=edit?projectById(selected):null;openModal(edit?'Un objetivo. Un rumbo.':'Dale un lugar a tu proyecto.',`<p class="modal-subtitle">${edit?'Guardá lo importante para retomar sin perder contexto.':'Tus archivos pueden seguir donde están. Empecemos por el objetivo.'}</p><form id="project-form" data-edit="${p?esc(p.id):''}"><div class="field"><label for="p-name">Nombre del proyecto</label><input id="p-name" name="name" required maxlength="120" placeholder="¿Qué estás construyendo?" value="${esc(p?.name)}"></div><div class="field"><label for="p-description">En una frase <small>Opcional</small></label><input id="p-description" name="description" maxlength="300" placeholder="La idea detrás del proyecto" value="${esc(p?.description)}"></div><div class="field"><label for="p-goal">¿Qué significa terminarlo?</label><textarea id="p-goal" name="goal" required placeholder="Ej.: publicar una primera versión donde pueda crear y guardar rutinas.">${esc(p?.goal)}</textarea></div><div class="field"><label for="p-path">Carpeta local <small>Opcional</small></label><input id="p-path" name="path" placeholder="C:\\Proyectos\\mi-app" value="${esc(p?.path)}"></div><p class="field-note">Se usa al ejecutar Nexo en tu equipo. La web no accede a tus carpetas.</p><div class="field"><label for="p-repository">Repositorio de GitHub <small>Opcional</small></label><input id="p-repository" name="repository" type="url" placeholder="https://github.com/usuario/proyecto" value="${esc(p?.repository)}"></div><details class="profile-fields" ${p?'open':''}><summary>Más contexto para tu yo del futuro</summary><div class="field"><label for="p-about">¿De qué se trata?</label><textarea id="p-about" name="about" placeholder="Qué hace, a quién ayuda y por qué lo empezaste…">${esc(p?.about)}</textarea></div><div class="field"><label for="p-stack">Tecnologías <small>Separadas por comas</small></label><input id="p-stack" name="stack" value="${esc(p?.stack)}" placeholder="React, Django, PostgreSQL"></div><div class="field"><label for="p-command">Cómo ejecutarlo</label><input id="p-command" name="runCommand" value="${esc(p?.runCommand)}" placeholder="npm run dev"></div><div class="field"><label for="p-website">URL del proyecto <small>Opcional</small></label><input id="p-website" name="website" type="url" value="${esc(p?.website)}" placeholder="https://mi-proyecto.com"></div><div class="field"><label for="p-next">¿Dónde lo dejé? ¿Cómo sigo?</label><textarea id="p-next" name="nextStep" placeholder="Lo último que hice, lo que me bloquea y el próximo paso…">${esc(p?.nextStep)}</textarea></div><div class="field"><label for="p-notes">Notas, decisiones y recordatorios</label><textarea id="p-notes" name="notes" placeholder="Todo eso que después te olvidás…">${esc(p?.notes)}</textarea></div></details>${!p?`<div class="field"><label>Un toque de color</label><input type="hidden" name="color" value="violet"><div class="color-picker">${Object.keys(colors).map(c=>`<button class="color-choice ${c==='violet'?'selected':''}" type="button" data-color="${c}" style="${theme({color:c})}" aria-label="Color ${c}" aria-pressed="${c==='violet'}"></button>`).join('')}</div></div>`:`<div class="field"><label for="p-status">Estado</label><select id="p-status" name="status">${[['active','En marcha'],['paused','En pausa'],['archived','Archivado']].map(([v,l])=>`<option value="${v}" ${p.status===v?'selected':''}>${l}</option>`).join('')}</select></div>`}<div class="form-actions"><button type="button" class="btn" data-action="close">Cancelar</button><button class="btn primary" type="submit">${p?'Guardar cambios':'Crear proyecto'}${icon('arrow')}</button></div></form>`,{large:true});}
function taskForm(status='pending'){if(!state.projects.some(p=>p.status!=='archived')){projectForm();return;}
 openModal('Un próximo paso concreto.',`<p class="modal-subtitle">Una tarea pequeña es más fácil de empezar. Y de terminar.</p><form id="task-form"><input type="hidden" name="status" value="${esc(status)}"><div class="field"><label for="t-title">¿Qué vas a hacer?</label><input name="title" id="t-title" required maxlength="200" placeholder="Ej.: conectar el formulario de registro"></div><div class="field"><label for="t-project">Proyecto</label><select name="projectId" id="t-project">${state.projects.filter(p=>p.status!=='archived').map(p=>`<option value="${esc(p.id)}" ${selected===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="t-description">Contexto <small>Opcional</small></label><textarea name="description" id="t-description" placeholder="Qué falta, por qué importa, cómo empezar…"></textarea></div><div class="field-row"><div class="field"><label for="t-priority">Prioridad</label><select id="t-priority" name="priority"><option value="medium">Media</option><option value="high">Alta</option><option value="low">Baja</option></select></div><div class="field"><label for="t-estimate">Tiempo estimado</label><input id="t-estimate" name="estimate" maxlength="40" placeholder="Ej.: 30 min"></div></div><div class="field"><label for="t-acceptance">Lista para terminar <small>Un criterio por línea</small></label><textarea id="t-acceptance" name="acceptance" placeholder="El usuario recibe un mensaje de confirmación."></textarea></div><label class="checkbox-label"><input name="today" type="checkbox" ${route==='today'?'checked':''}>Reservarle un lugar en Mi día</label><div class="form-actions"><button type="button" class="btn" data-action="close">Cancelar</button><button type="submit" class="btn primary">Crear tarea ${icon('plus')}</button></div></form>`);
}
function taskDrawer(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;openedTask=id;const p=projectById(t.projectId);openModal(badge(p),`<form id="task-detail" data-id="${esc(id)}"><div class="field"><label for="d-title">TAREA · NX-${state.tasks.indexOf(t)+1}</label><input name="title" id="d-title" required maxlength="200" value="${esc(t.title)}" style="font-size:18px;font-weight:550;background:white"></div><div class="field-row"><div class="field"><label for="d-status">Estado</label><select name="status" id="d-status">${Object.entries(labels).map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="d-priority">Prioridad</label><select name="priority" id="d-priority">${Object.entries(priorityLabel).map(([v,l])=>`<option value="${v}" ${t.priority===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="field"><label for="d-description">Contexto y próximo paso</label><textarea id="d-description" name="description">${esc(t.description)}</textarea></div><div class="field"><label for="d-acceptance">Criterios de aceptación <small>Uno por línea</small></label><textarea id="d-acceptance" name="acceptance">${esc((t.acceptance||[]).join('\n'))}</textarea></div><div class="field"><label for="d-estimate">Tiempo estimado</label><input name="estimate" id="d-estimate" value="${esc(t.estimate)}" maxlength="40" placeholder="Ej.: 30 min"></div><label class="checkbox-label"><input type="checkbox" name="today" ${t.today?'checked':''}>${icon('sun')}Para hoy</label>${t.source?`<div class="task-evidence"><strong>EVIDENCIA / ORIGEN</strong>${esc(t.source)}</div>`:''}<p class="field-note" style="margin-top:18px">Terminada significa que verificaste el resultado y sus criterios.</p><div class="drawer-footer"><button type="button" class="icon-btn" data-delete-task="${esc(id)}" aria-label="Eliminar tarea">${icon('trash')}</button><button type="submit" class="btn primary">${icon('check')}Guardar cambios</button></div></form>`,{drawer:true});}
function settings(){openModal('Tu espacio, a tu manera.',`<form id="settings-form"><div class="field"><label for="s-name">Nombre del workspace</label><input id="s-name" name="name" maxlength="80" value="${esc(state.settings?.name||'Mi espacio')}"></div><div class="field"><label for="s-limit">Objetivo de tareas por día</label><input id="s-limit" name="dailyLimit" type="number" min="1" max="10" value="${Number(state.settings?.dailyLimit)||3}"></div><p class="field-note">Un recordatorio para priorizar. Podés seleccionar más tareas si lo necesitás.</p><div class="form-actions"><button class="btn primary">Guardar preferencias</button></div></form><div class="settings-actions" style="margin-top:22px"><button class="btn" data-action="export">${icon('download')}Exportar espacio</button><button class="btn" data-action="import">${icon('upload')}Importar espacio</button>${installEvent?'<button class="btn" data-action="install">Instalar app</button>':''}</div><p class="modal-subtitle" style="margin-top:17px">${local?'El tablero y el MCP usan el mismo archivo en tu equipo.': 'La versión web guarda los datos en este navegador. Exportá una copia para trasladarlos o conservar un respaldo.'}</p><div class="footer-version">Nexo alpha · 0.1.0 · Sin sincronización en la nube</div>`);}
function confirmModal(title,text,action,label='Continuar'){openModal(esc(title),`<p class="modal-subtitle">${esc(text)}</p><div class="form-actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="${action}">${label}</button></div>`);}
function searchModal(){openModal('Encontrá tu próximo paso.',`<input class="search-input" id="global-query" placeholder="Buscar tareas y proyectos…" autocomplete="off" aria-label="Buscar tareas y proyectos"><div class="search-results" id="search-results"><p class="small-muted">Escribí un título, un proyecto o una palabra clave.</p></div>`,{large:true});}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado. Listo para pegar en tu terminal.');}catch{openModal('Copiá este comando',`<pre>${esc(text)}</pre>`);}}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`nexo-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Espacio exportado. Guardalo como respaldo.');}
async function analyzeProject(){
 if(!local){navigate('integrations');toast('El análisis de carpetas se ejecuta con Nexo local y Claude Code.');return;}
 if(!selected){const ps=state.projects.filter(p=>p.status==='active');if(!ps.length){projectForm();return;}openModal('¿En qué proyecto avanzamos?',`<p class="modal-subtitle">Claude revisará su carpeta y objetivo. Las propuestas aparecerán en Sugerencias. Usa tu sesión y límites de Claude Code.</p><div class="nav-list">${ps.map(p=>`<button class="workspace-switch" data-analyze-project="${esc(p.id)}"><span class="project-logo" style="${theme(p)}">${projectIcon(p)}</span><span class="workspace-copy"><b>${esc(p.name)}</b><small>${esc(p.path||'Primero vinculá una carpeta')}</small></span>${icon('chevron')}</button>`).join('')}</div>`);return;}
 const p=projectById(selected);if(!p.path||!p.goal){projectForm(true);toast('Completá la carpeta local y el objetivo para analizarlo.');return;}
 try{const job=await request('/api/analyze',{method:'POST',body:JSON.stringify({projectId:p.id})});jobs.push(job);closeOverlay();render();toast('Análisis iniciado. Podés seguir usando el tablero.');}catch(e){toast(e.message,true);}
}
async function action(name,el){
 switch(name){
  case 'new-project':projectForm();break;case 'edit-project':projectForm(true);break;case 'new-task':taskForm(el?.dataset.status||'pending');break;
  case 'copy-path':await copy(projectById(selected)?.path||'');break;case 'copy-run':await copy(projectById(selected)?.runCommand||'');break;case 'close':closeOverlay();break;case 'settings':settings();break;case 'toggle-theme':appearance=appearance==='dark'?'light':'dark';localStorage.setItem(THEME_KEY,appearance);applyAppearance();render();if(overlay.firstElementChild)settings();toast(`Tema ${appearance==='dark'?'oscuro':'claro'} activado.`);break;case 'search':searchModal();break;case 'export':exportData();break;case 'import':document.querySelector('#import-file').click();break;
  case 'menu':document.querySelector('.sidebar').classList.toggle('open');break;
  case 'analyze':await analyzeProject();break;case 'copy-mcp':await copy(mcpCommand());break;
  case 'start-fresh':confirmModal('Un espacio para tus proyectos.','Vamos a quitar los proyectos de ejemplo. Los proyectos que hayas creado se conservan.','confirm-fresh','Empezar');break;
  case 'confirm-fresh':{const clean=emptyState();clean.settings=state.settings;clean.projects=state.projects.filter(p=>!p.id.startsWith('demo-'));clean.tasks=state.tasks.filter(t=>clean.projects.some(p=>p.id===t.projectId));await replace(clean);closeOverlay();navigate('overview');if(!clean.projects.length)projectForm();else toast('Tu espacio, listo. Conservamos tus proyectos.');break;}
  case 'install':if(installEvent){await installEvent.prompt();installEvent=null;}break;
  case 'confirm-delete':{const id=el.dataset.id;await mutate({type:'task.delete',id});closeOverlay();toast('Tarea eliminada.');break;}
 }
}
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-route],[data-project],[data-task],[data-tab],[data-action],[data-color],[data-accept],[data-discard],[data-restore],[data-analyze-project],[data-delete-task]');
 if(!el){if(e.target.classList.contains('backdrop'))closeOverlay();return;}
 try{
  if(el.dataset.route){closeOverlay();navigate(el.dataset.route);}
  else if(el.dataset.project){closeOverlay();navigate('overview',el.dataset.project);}
  else if(el.dataset.task)taskDrawer(el.dataset.task);
  else if(el.dataset.tab){tab=el.dataset.tab;render();}
  else if(el.dataset.action)await action(el.dataset.action,el);
  else if(el.dataset.color){overlay.querySelector('input[name=color]').value=el.dataset.color;overlay.querySelectorAll('.color-choice').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',b===el?'true':'false');});}
  else if(el.dataset.accept){await mutate({type:'task.update',id:el.dataset.accept,patch:{suggested:false}});toast('Una tarea más clara. Ya está en tu tablero.');}
  else if(el.dataset.discard){await mutate({type:'task.delete',id:el.dataset.discard});toast('Sugerencia descartada.');}
  else if(el.dataset.restore){await mutate({type:'project.update',id:el.dataset.restore,patch:{status:'active'}});toast('Proyecto restaurado.');}
  else if(el.dataset.analyzeProject){selected=el.dataset.analyzeProject;await analyzeProject();}
  else if(el.dataset.deleteTask){const id=el.dataset.deleteTask;confirmModal('¿Eliminar esta tarea?','La tarea se quitará del tablero. Esta acción no se puede deshacer.','confirm-delete','Eliminar tarea');overlay.querySelector('[data-action="confirm-delete"]').dataset.id=id;}
 }catch(err){toast(err.message,true);}
});
document.addEventListener('submit',async e=>{
 if(!['project-form','task-form','task-detail','settings-form'].includes(e.target.id))return;e.preventDefault();const form=e.target;const data=Object.fromEntries(new FormData(form));const button=form.querySelector('[type=submit],button:not([type])');if(button)button.disabled=true;
 try{
  if(form.id==='project-form'){if(data.repository&&!/^https:\/\/github\.com\/[\w.-]+\/[\w.-]+\/?$/.test(data.repository))throw Error('Usá una URL de repositorio de GitHub válida.');const editing=form.dataset.edit;const s=await mutate(editing?{type:'project.update',id:editing,patch:data}:{type:'project.create',project:data});closeOverlay();navigate('overview',editing||s.projects.at(-1).id);toast(editing?'Proyecto actualizado.':'Tu proyecto ya tiene un lugar.');}
  if(form.id==='task-form'||form.id==='task-detail'){data.acceptance=data.acceptance.split('\n').map(x=>x.trim()).filter(Boolean);data.today=form.querySelector('[name=today]').checked;await mutate(form.id==='task-form'?{type:'task.create',task:data}:{type:'task.update',id:form.dataset.id,patch:data});closeOverlay();toast(form.id==='task-form'?'Un próximo paso, listo.':'Cambios guardados.');}
  if(form.id==='settings-form'){await mutate({type:'settings.update',settings:data});closeOverlay();toast('Tu espacio, actualizado.');}
 }catch(err){errorInForm(err);if(button)button.disabled=false;}
});
document.addEventListener('input',e=>{
 if(e.target.id==='board-search'){search=e.target.value;document.querySelector('#board-contents').innerHTML=boardContents();}
 if(e.target.id==='global-query'){const query=e.target.value.trim().toLowerCase();const ps=state.projects.filter(p=>query&&(p.name+' '+p.goal).toLowerCase().includes(query));const ts=state.tasks.filter(t=>query&&(t.title+' '+t.description+' '+projectById(t.projectId)?.name).toLowerCase().includes(query)).slice(0,15);document.querySelector('#search-results').innerHTML=query?ps.map(p=>`<button class="workspace-switch" data-project="${esc(p.id)}"><span class="project-logo" style="${theme(p)}">${projectIcon(p)}</span><span>${esc(p.name)}</span></button>`).join('')+ts.map(taskCard).join('')||'<p class="small-muted">No encontramos coincidencias.</p>':'<p class="small-muted">Escribí para buscar.</p>';}
});
document.addEventListener('change',e=>{if(e.target.id==='priority-filter')priority=e.target.value;else if(e.target.id==='project-filter')projectFilter=e.target.value;else if(e.target.id==='status-filter')taskStatus=e.target.value;else return;document.querySelector('#board-contents').innerHTML=boardContents();});
document.addEventListener('keydown',e=>{
 if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal();}
 if(e.key==='Escape'){closeOverlay();document.querySelector('.sidebar')?.classList.remove('open');}
 if((e.key==='Enter'||e.key===' ')&&e.target.matches('.task-card,[data-task][tabindex]')){e.preventDefault();taskDrawer(e.target.dataset.task);}
 if(e.key==='Tab'&&overlay.firstElementChild){const focus=[...overlay.querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled&&n.type!=='hidden');if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
let dragged=null;
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-task]');if(!card)return;dragged=card.dataset.task;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.effectAllowed='move';card.classList.add('dragging');});
document.addEventListener('dragover',e=>{const col=e.target.closest('[data-drop-status]');if(col&&dragged){e.preventDefault();col.classList.add('drop-over');}});
document.addEventListener('dragleave',e=>{const col=e.target.closest('[data-drop-status]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drop-over');});
document.addEventListener('dragend',()=>{dragged=null;document.querySelectorAll('.dragging,.drop-over').forEach(el=>el.classList.remove('dragging','drop-over'));});
document.addEventListener('drop',async e=>{const col=e.target.closest('[data-drop-status]');if(!col||!dragged)return;e.preventDefault();const id=dragged;dragged=null;const t=state.tasks.find(t=>t.id===id);if(!t||t.status===col.dataset.dropStatus){render();return;}try{await mutate({type:'task.update',id,patch:{status:col.dataset.dropStatus}});toast(`Tarea movida a ${labels[col.dataset.dropStatus]}.`);}catch(err){toast(err.message,true);render();}});
document.querySelector('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>5_000_000)throw Error('El archivo supera el límite de 5 MB.');const next=validateState(JSON.parse(await f.text()));openModal('¿Importar este espacio?',`<p class="modal-subtitle">Vas a reemplazar el espacio actual por ${next.projects.length} proyectos y ${next.tasks.length} tareas. Exportá el espacio actual si querés conservarlo.</p><div class="form-actions"><button class="btn" data-action="export">Exportar actual</button><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="confirm-import">Importar espacio</button></div>`);document.querySelector('#confirm-import').addEventListener('click',async()=>{try{await replace(next);closeOverlay();navigate('overview');toast('Espacio importado.');}catch(err){toast(err.message,true);}});}catch(err){toast(err.message,true);}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
window.addEventListener('storage',e=>{if(!local&&e.key===KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));render();}catch{toast('No se pudo leer el cambio de otra ventana.',true);}}});
async function poll(){if(!local)return;try{const s=await request('/api/state');if(s.revision!==state.revision){state=s;render();}const next=await request('/api/jobs');for(const j of next){const prev=jobs.find(p=>p.id===j.id);if(prev?.status==='running'&&j.status!=='running')toast(j.status==='completed'?`${j.count} sugerencias listas para revisar.`:j.error,j.status==='failed');}if(JSON.stringify(next)!==JSON.stringify(jobs)){jobs=next;render();}}catch(e){if(!document.hidden)console.warn('Nexo local:',e.message);}}
async function boot(){
 try{const r=await fetch('/api/health',{signal:AbortSignal.timeout(2500)});if(r.ok){const d=await r.json();if(d.local)local=d;}}catch{}
 try{if(local)state=await request('/api/state');else{const saved=localStorage.getItem(KEY);state=saved?validateState(JSON.parse(saved)):demoState();if(!saved)persist(state);}}catch(e){app.innerHTML=`<main class="content"><div class="error-banner">No pudimos abrir tu espacio: ${esc(e.message)}. No se sobrescribió ningún dato. Recuperá tu respaldo o revisá el almacenamiento antes de recargar.</div></main>`;return;}
 const hash=location.hash.slice(1);if(hash.startsWith('project/')){selected=decodeURIComponent(hash.slice(8));route='overview';}else if(['overview','today','inbox','projects','integrations','archived'].includes(hash))route=hash;
 render();
 if(local){setInterval(poll,2000);request('/api/claude').then(x=>{claudeAvailable=x.available;}).catch(()=>{});}
 else if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
}
boot();
// Un proyecto puede nacer sin objetivo; solo el análisis con IA exige uno.
new MutationObserver(()=>{const goal=overlay.querySelector('#p-goal[required]');if(goal){goal.required=false;const label=overlay.querySelector('label[for="p-goal"]');if(label&&!label.textContent.includes('Opcional'))label.innerHTML='¿Qué significa terminarlo? <small>Opcional por ahora</small>';}}).observe(overlay,{childList:true,subtree:true});
